insert into public.flashcards(id,polish,translation,example,position,is_active,source_metadata) values
('b1trip-przesiadka','przesiadka','пересадка','Na przesiadkę mamy tylko dwanaście minut.',377,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-opoznienie','opóźnienie','задержка','Pociąg ma czterdzieści minut opóźnienia.',378,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-polaczenie','połączenie','сообщение; рейс','Czy jest inne połączenie do Pragi?',379,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-peron','peron','платформа','Pociąg odjedzie z trzeciego peronu.',380,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-odwolany','odwołany','отменённый','Nasz lot został odwołany z powodu burzy.',381,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-zglosic','zgłosić problem','сообщить о проблеме','Zgłosiliśmy problem pracownikowi informacji.',382,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-zastepczy','zastępczy','заменяющий','Przewoźnik zapewnił autobus zastępczy.',383,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-zwrot','zwrot kosztów','возврат расходов','Poprosiła o zwrot kosztów biletu.',384,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-dojechac','dojechać','доехать','Mimo opóźnienia dojechaliśmy przed północą.',385,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-wyjechac','wyjechać','уехать; выехать','Wyjechaliśmy z domu bardzo wcześnie.',386,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-przyjechac','przyjechać','приехать','Autobus przyjechał na czas.',387,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-przejechac','przejechać','проехать','W jeden dzień przejechaliśmy pięćset kilometrów.',388,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-ominac','ominąć','обойти; миновать','Kierowca ominął korek lokalną drogą.',389,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-utknac','utknąć','застрять','Utknęliśmy na lotnisku na kilka godzin.',390,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}'),('b1trip-wrazenie','niezapomniane wrażenie','незабываемое впечатление','Widok z pociągu zrobił na mnie niezapomniane wrażenie.',391,true,'{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29"}') on conflict(id) do update set polish=excluded.polish,translation=excluded.translation,example=excluded.example,position=excluded.position,is_active=excluded.is_active,source_metadata=excluded.source_metadata;
insert into public.reading_texts(id,topic_id,title,description,level,minutes,emoji,paragraphs,glossary,source_metadata,position,is_active) values ('b1trip-nieplanowana-przesiadka','b1-travel','Nieplanowana przesiadka','Задержка, альтернативный маршрут и неожиданные впечатления','B1',8,'🚆','["Marta i Paweł wyjechali rano z Warszawy do Pragi. Mieli przesiadkę w Katowicach, a cały plan wydawał się prosty. Jednak przed Katowicami pociąg zatrzymał się na trasie. Po kilkunastu minutach konduktor poinformował pasażerów o poważnym opóźnieniu.","Na przesiadkę mieli tylko dwadzieścia minut, więc istniało ryzyko, że nie zdążą na kolejne połączenie. Po przyjeździe szybko poszli do punktu informacji. Pracownica sprawdziła bilety i zaproponowała im inną trasę przez Ostrawę. Nowe połączenie odjeżdżało z sąsiedniego peronu.","Podróżni dojechali do Ostrawy bez problemu, lecz na pociąg do Pragi musieli czekać prawie dwie godziny. Zamiast siedzieć na dworcu, zostawili bagaż w przechowalni i poszli na krótki spacer po centrum. Obejrzeli rynek i zjedli obiad w małej restauracji.","Do Pragi przyjechali późnym wieczorem. Podróż trwała znacznie dłużej, niż planowali, ale Marta nie uważała jej za nieudaną. Stwierdziła, że dzięki spokojnej rozmowie i szybkiemu znalezieniu innego połączenia problem zmienił się w niezapomniane doświadczenie."]','{"wydawał":{"lemma":"wydawać się","translation":"казаться","part_of_speech":"глагол"},"trasie":{"lemma":"trasa","translation":"маршрут","part_of_speech":"существительное"},"konduktor":{"lemma":"konduktor","translation":"проводник; контролёр","part_of_speech":"существительное"},"poważnym":{"lemma":"poważny","translation":"серьёзный","part_of_speech":"прилагательное"},"ryzyko":{"lemma":"ryzyko","translation":"риск","part_of_speech":"существительное"},"zdążą":{"lemma":"zdążyć","translation":"успеть","part_of_speech":"глагол"},"sąsiedniego":{"lemma":"sąsiedni","translation":"соседний","part_of_speech":"прилагательное"},"przechowalni":{"lemma":"przechowalnia","translation":"камера хранения","part_of_speech":"существительное"},"znacznie":{"lemma":"znacznie","translation":"значительно","part_of_speech":"наречие"},"nieudaną":{"lemma":"nieudany","translation":"неудачный","part_of_speech":"прилагательное"},"stwierdziła":{"lemma":"stwierdzić","translation":"заключить; отметить","part_of_speech":"глагол"},"doświadczenie":{"lemma":"doświadczenie","translation":"опыт","part_of_speech":"существительное"}}','{"origin":"original","created_for":"PolskiFlow","verified_at":"2026-08-29","comprehension_lesson_id":"b1trip-reading-check"}',25,true) on conflict(id) do update set topic_id=excluded.topic_id,title=excluded.title,description=excluded.description,level=excluded.level,minutes=excluded.minutes,emoji=excluded.emoji,paragraphs=excluded.paragraphs,glossary=excluded.glossary,source_metadata=excluded.source_metadata,position=excluded.position,is_active=excluded.is_active;
