delete from public.lesson_flashcards where lesson_id in ('b1trip-words','b1trip-review'); insert into public.lesson_flashcards(lesson_id,flashcard_id,position) values ('b1trip-words','b1trip-przesiadka',0),('b1trip-words','b1trip-opoznienie',1),('b1trip-words','b1trip-polaczenie',2),('b1trip-words','b1trip-peron',3),('b1trip-words','b1trip-odwolany',4),('b1trip-words','b1trip-zglosic',5),('b1trip-words','b1trip-zastepczy',6),('b1trip-words','b1trip-zwrot',7),('b1trip-review','b1trip-dojechac',0),('b1trip-review','b1trip-wyjechac',1),('b1trip-review','b1trip-przyjechac',2),('b1trip-review','b1trip-przejechac',3),('b1trip-review','b1trip-ominac',4),('b1trip-review','b1trip-utknac',5),('b1trip-review','b1trip-wrazenie',6);
delete from public.questions where lesson_id in ('b1trip-grammar','b1trip-quiz','b1trip-reading-check'); insert into public.questions(lesson_id,prompt,options,correct,explanation,position) values
('b1trip-grammar','Musimy ___ do Krakowa przed osiemnastą.','["dojechać","wyjechać z","przejeżdżać od"]',0,'Dojechać обозначает достижение пункта назначения.',0),('b1trip-grammar','Pociąg ___ z Warszawy o 7:10 i ___ do Gdańska o 10:05.','["wyjeżdża; przyjeżdża","dojeżdża; wyjeżdża","przejeżdża; odjeżdża z"]',0,'Wyjeżdża z называет исходную точку, przyjeżdża do — конечную.',1),('b1trip-grammar','Wczoraj ___ przez Łódź, ale nie zatrzymywaliśmy się tam.','["przejechaliśmy","dojechaliśmy do","wyjechaliśmy z"]',0,'Przejechać przez — проехать через место.',2),('b1trip-grammar','Составьте: Из-за задержки мы не успели на пересадку.','["Z powodu opóźnienia nie zdążyliśmy na przesiadkę.","Dzięki opóźnieniu nie zdążamy do przesiadki.","Opóźnienie przez przesiadkę nie przyjechało."]',0,'Z powodu вводит причину, zdążyć na требует винительного падежа.',3),('b1trip-grammar','Gdy lot odwołano, pasażerowie ___ na lotnisku.','["utknęli","ominęli","dojechali"]',0,'Utknąć означает оказаться без возможности продолжить путь.',4),('b1trip-grammar','Составьте: Сотрудник предложил нам другой рейс.','["Pracownik zaproponował nam inne połączenie.","Pracownik zaproponował nas innym połączeniem.","Inne połączenie proponuje do pracownika."]',0,'Zaproponować komu? требует дательного: nam; co? — винительного: połączenie.',5),
('b1trip-quiz','Что означает przesiadka?','["пересадка","платформа","багаж"]',0,'Przesiadka — смена транспорта по пути.',0),('b1trip-quiz','Lot został ___ z powodu złej pogody.','["odwołany","przejechany","ominięty do"]',0,'Odwołany lot не состоится.',1),('b1trip-quiz','Как попросить возврат расходов?','["Proszę o zwrot kosztów.","Proszę przejechać koszt.","Zwrot jedzie do mnie."]',0,'Prosić o zwrot kosztów — стандартная просьба о возмещении.',2),('b1trip-quiz','Autobus zastępczy ___ pasażerów do następnej stacji.','["zawiózł","wyjechał pasażerów","utknął do"]',0,'Zawieźć kogoś do места — доставить кого-либо.',3),('b1trip-quiz','Który czasownik podkreśla osiągnięcie celu?','["dojechać","jechać","przejeżdżać"]',0,'Приставка do- подчёркивает достижение конечной точки.',4),('b1trip-quiz','Pociąg odjedzie z ___.','["peronu","połączenia","opóźnieniem do"]',0,'Поезд отправляется с платформы: z peronu.',5),('b1trip-quiz','Co robisz, gdy biletomat nie działa?','["Zgłaszam problem pracownikowi.","Odwołuję peron.","Przejeżdżam informację."]',0,'Zgłosić problem — сообщить сотруднику о неисправности.',6),('b1trip-quiz','Kierowca ___ zamkniętą drogę.','["ominął","utknął ją do","dojechał przez ją"]',0,'Ominąć — выбрать путь в обход препятствия.',7),('b1trip-quiz','Как связать проблему и решение?','["Z powodu opóźnienia spóźniliśmy się, dlatego wybraliśmy inny pociąg.","Dzięki problemowi, chociaż dlatego pociąg.","Opóźnienie albo rozwiązanie że."]',0,'Z powodu вводит причину, dlatego — следствие и решение.',8),('b1trip-quiz','Podróż zrobiła na mnie duże ___.','["wrażenie","połączenie","opóźnienie"]',0,'Zrobić wrażenie — произвести впечатление.',9),
('b1trip-reading-check','Dokąd jechali Marta i Paweł?','["Do Pragi","Do Wiednia","Do Gdańska"]',0,'Они ехали поездом в Прагу.',0),('b1trip-reading-check','Gdzie pojawił się pierwszy problem?','["W Katowicach","W Krakowie","W Pradze"]',0,'В Катовице объявили о большой задержке.',1),('b1trip-reading-check','Dlaczego mogli stracić połączenie?','["Mieli krótką przesiadkę","Zgubili paszporty","Kupili zły bilet"]',0,'Из-за задержки они могли не успеть на короткую пересадку.',2),('b1trip-reading-check','Jak pomogła pracownica informacji?','["Znalazła inne połączenie przez Ostrawę","Oddała im samochód","Odwołała wszystkie pociągi"]',0,'Сотрудница предложила альтернативный маршрут через Остраву.',3),('b1trip-reading-check','Co zrobili podczas dodatkowego czasu?','["Krótko zwiedzili centrum Ostrawy","Wrócili do Warszawy","Czekali cały dzień na peronie"]',0,'Они использовали паузу для короткой прогулки.',4),('b1trip-reading-check','Jaki jest główny wniosek Marty?','["Problem w podróży może zmienić się w ciekawe doświadczenie","Nie warto pytać o inne połączenie","Każde opóźnienie kończy podróż"]',0,'Марта оценила неожиданное изменение как полезный опыт.',5);
